function intervalTimer(loginExtend){
  
    let count = 0;
    
    timerId = setInterval(()=> {
        const leftTime = Number(loginExtend*60) - count;
        count++;
        
        postMessage({ type:'timer', leftTime});
        
        if(leftTime <= 60){
          postMessage({ type:'showPopup', leftTime:leftTime});
        }
        if(leftTime == 0){
          postMessage({ type:'timer-end' });
          timerId && clearInterval(timerId);
        }
    },1000);
}

onmessage = function(e){
  const {type, loginExtend } = e.data;
  switch(type){
    case 'start-timer':
          clearInterval(timerId);
          timerId = null;
          intervalTimer(loginExtend);
    break;
  }
};

